	// Hand-fix (handfixes.json zoom-token-form-auth): the pair rides in the form, never HTTP Basic.
	form := url.Values{
		"grant_type":    {"account_credentials"},
		"account_id":    {accountID},
		"client_id":     {clientID},
		"client_secret": {clientSecret},
	}
	if scope := resolveClientCredentialsScope(); scope != "" {
		form.Set("scope", scope)
	}
	encoded := cliutil.TokenForm(form)
	req, err := http.NewRequest(http.MethodPost, tokenURL, strings.NewReader(encoded))
	if err != nil {
		return nil, fmt.Errorf("building token request: %w", client.ZoomMaskTransportError(err, nil, clientSecret)) // zoom-phone hand-fix: credkit-wiring
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("User-Agent", resolveClientCredentialsUserAgent())
	req, err = client.GuardTokenRequest(httpClient, req, []byte(encoded))
	if err != nil {
		return nil, err
	}

	resp, err := cliutil.OAuthTokenHTTPClient(httpClient).Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling token endpoint: %w", client.ZoomMaskTransportError(err, req, clientSecret)) // zoom-phone hand-fix: credkit-wiring
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("token endpoint returned %s", client.ZoomTokenEndpointError(resp.StatusCode, body)) // zoom-phone hand-fix: zoom-phone-token-error-allowlist
	}
	var tok tokenResponse
	if err := json.Unmarshal(body, &tok); err != nil {
		return nil, client.ZoomTokenResponseUnreadable(resp.StatusCode) // zoom-phone hand-fix: zoom-phone-token-error-allowlist
	}
	if tok.AccessToken == "" {
		return nil, fmt.Errorf("token response missing access_token")
	}
	return &tok, nil
